"""Data sources of this connector, declared by tool name (generated by connector-ontology-map migrate).

Served live as ``connector://resources``. Regenerate by editing the declarations, not the tools.
"""

# ruff: noqa: E501
from __future__ import annotations

from agent_connector_sdk.ingest.sources import IngestSourceDeclaration, IngestSourceSpec

CONNECTOR = "lucerna-mcp"

SOURCES = ()

SCHEMA_MAPPINGS = {
    "IndexingRun": {
        "fields": {},
        "ontology_class": None,
    },
    "SearchAlias": {
        "fields": {},
        "ontology_class": None,
    },
    "SearchIndex": {
        "fields": {},
        "ontology_class": None,
    },
}

RESOURCES = (
    {
        "id_prefix": "indexingrun",
        "label": "Indexing Run",
        "name": "IndexingRun",
    },
    {
        "id_prefix": "searchalias",
        "label": "Search Alias",
        "name": "SearchAlias",
    },
    {
        "id_prefix": "searchindex",
        "label": "Search Index",
        "name": "SearchIndex",
    },
)


def declaration() -> IngestSourceDeclaration:
    """The declaration the server assembles from this module."""
    specs = []
    for item in SOURCES:
        for entry in item["connector_sources"]:
            body = {k: v for k, v in entry.items() if k not in ("tool", "mapping")}
            specs.append(
                IngestSourceSpec.model_validate({**body, "tools": (entry["tool"],)})
            )
    return IngestSourceDeclaration.model_validate(
        {
            "connector": CONNECTOR,
            "sources": specs,
            "schema_mappings": SCHEMA_MAPPINGS,
            "resources": RESOURCES,
        }
    )
